         .flags
     & 8)
    == 0) {
    float effect_heading =
        player_state_table[render_overlay_player_index].aim_heading
        + 1.5707964f;
    render_delta.x = (float)cos(effect_heading)
                * player_state_table[render_overlay_player_index]
                      .muzzle_flash_alpha
                * 12.0f
